/**
 * District lists for the city type-ahead.
 *
 * Each state's list is its own small JSON chunk (src/data/districts/<CODE>.json,
 * generated by scripts/build-districts.mjs), fetched only once a state is
 * picked. The names are the canonical English ones; they are what is saved,
 * and the database accepts only a (state, city) pair from the same list.
 */
const FILES = import.meta.glob('../data/districts/*.json', { import: 'default' });

const cache = new Map();

/** Resolves to { districts: string[], aliases: { [oldName]: canonical } }. */
export function loadDistricts(code) {
  if (!cache.has(code)) {
    const load = FILES[`../data/districts/${code}.json`];
    const promise = load
      ? load().then((data) => ({ districts: data.districts ?? [], aliases: data.aliases ?? {} }))
      : Promise.reject(new Error(`No district list for ${code}`));
    // A failed fetch (flaky connection) is not cached, so picking the state again retries.
    promise.catch(() => cache.delete(code));
    cache.set(code, promise);
  }
  return cache.get(code);
}

/** Lower case, accents and punctuation removed: "Sri Muktsar Sahib" -> "sri muktsar sahib". */
export function normalizePlace(text) {
  return String(text ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** Levenshtein distance between two short strings. */
function editDistance(a, b) {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i += 1) {
    const row = [i];
    for (let j = 1; j <= b.length; j += 1) {
      row[j] = Math.min(prev[j] + 1, row[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = row;
  }
  return prev[b.length];
}

/**
 * The districts that best match what was typed, best first.
 * Whole-name prefix beats a word prefix, which beats a match anywhere.
 * A former name ("Gurgaon") finds the current one ("Gurugram").
 */
export function matchDistricts(list, query, limit = 8) {
  const q = normalizePlace(query);
  if (!list) return [];
  // Nothing typed yet: the whole state's list, to scroll through.
  if (!q) return list.districts;

  const score = new Map();
  const consider = (name, text, bonus = 0) => {
    const n = normalizePlace(text);
    let rank;
    if (n === q) rank = 0;
    else if (n.startsWith(q)) rank = 1;
    else if (n.split(' ').some((word) => word.startsWith(q))) rank = 2;
    else if (n.includes(q)) rank = 3;
    // Spelling slips and official spellings people do not use ("Sundargarh"
    // for Sundaragada, "Morigaon" for Marigaon): close enough to the start of the name.
    else if (q.length >= 4 && editDistance(q, n.slice(0, q.length)) <= (q.length >= 7 ? 2 : 1)) rank = 4;
    else return;
    rank += bonus;
    if (!score.has(name) || score.get(name) > rank) score.set(name, rank);
  };
  for (const name of list.districts) consider(name, name);
  // Former names rank just below a match on the current name.
  for (const [alias, name] of Object.entries(list.aliases)) consider(name, alias, 0.5);

  return [...score.entries()]
    .sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([name]) => name);
}

/** The canonical district for text that names one exactly (current or former name), else null. */
export function exactDistrict(list, text) {
  const q = normalizePlace(text);
  if (!list || !q) return null;
  const hit = list.districts.find((name) => normalizePlace(name) === q);
  if (hit) return hit;
  const alias = Object.keys(list.aliases).find((name) => normalizePlace(name) === q);
  return alias ? list.aliases[alias] : null;
}
